// Core tests: the 24 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. The worked anchors below were independently recalculated with
// Python fractions/Decimal from the SPEC's pinned formulas before being
// written here.

import assert from "node:assert/strict";
import test from "node:test";
import { formatNumber, formatPercent, run } from "../public/js/core/inflation.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const rateBase = { mode: "rate", amount: "100000", annualRatePercent: "2", years: "10" };
const cpiBase = {
  mode: "cpi",
  amount: "30000",
  cpiFrom: "100.0",
  cpiTo: "109.2",
  labelFrom: "2015",
  labelTo: "2025",
  yearsBetween: null,
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("worked anchors: 3% for one year, and CPI 100 to 110 over five years", () => {
  // 10000 at 3% for 1 year: base 1.03, factor 1.03; future 10300;
  // purchasing power 10000 / 1.03 = 9708.7378... -> 9708.74; cumulative 3.
  const oneYear = run({ mode: "rate", amount: "10000", annualRatePercent: "3", years: "1" });
  assert.equal(oneYear.ok, true);
  assert.deepEqual(oneYear.result, {
    cumulativePercent: 3,
    futureValue: 10300,
    purchasingPower: 9708.74,
    yearTable: [
      { year: 0, nominalValue: 10000, purchasingPower: 10000 },
      { year: 1, nominalValue: 10300, purchasingPower: 9708.74 },
    ],
  });
  // CPI 100.0 -> 110.0, amount 20000, 5 years: ratio 1.1, adjusted
  // 22000, cumulative 10; equivalent annual rate (1.1^0.2 - 1) * 100 =
  // 1.92448... -> 1.9245.
  const cpi = run({
    mode: "cpi",
    amount: "20000",
    cpiFrom: "100.0",
    cpiTo: "110.0",
    labelFrom: "2020",
    labelTo: "2025",
    yearsBetween: "5",
  });
  assert.equal(cpi.ok, true);
  assert.deepEqual(cpi.result, {
    adjustedAmount: 22000,
    cumulativePercent: 10,
    equivalentAnnualRatePercent: 1.9245,
    fromLabel: "2020",
    toLabel: "2025",
  });
});

test("specified boundary checks: amount, rate, CPI and years limits", () => {
  assert.equal(run({ ...rateBase, amount: "999999999.99" }).ok, true);
  assert.deepEqual(errorOf({ ...rateBase, amount: "1000000000" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...rateBase, amount: "99999999.999" }), {
    code: "DECIMAL_FORMAT",
    field: "amount",
    row: null,
  });
  assert.equal(run({ ...rateBase, annualRatePercent: "1000" }).ok, true);
  assert.deepEqual(errorOf({ ...rateBase, annualRatePercent: "1000.001" }), {
    code: "RANGE",
    field: "annualRatePercent",
    row: null,
  });
  assert.deepEqual(errorOf({ ...rateBase, annualRatePercent: "-100.001" }), {
    code: "RANGE",
    field: "annualRatePercent",
    row: null,
  });
  assert.equal(run({ ...cpiBase, cpiFrom: "99999.999" }).ok, true);
  assert.deepEqual(errorOf({ ...cpiBase, cpiFrom: "100000" }), {
    code: "RANGE",
    field: "cpiFrom",
    row: null,
  });
  assert.equal(run({ ...rateBase, years: "200" }).ok, true);
  assert.deepEqual(errorOf({ ...rateBase, years: " 10" }), {
    code: "INTEGER_FORMAT",
    field: "years",
    row: null,
  });
});

test("capacity: an over-long raw value is INPUT_LIMIT before grammar", () => {
  assert.deepEqual(errorOf({ ...rateBase, amount: "1234567890123" }), {
    code: "INPUT_LIMIT",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...rateBase, annualRatePercent: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "annualRatePercent",
    row: null,
  });
  assert.deepEqual(errorOf({ ...cpiBase, cpiFrom: "1234567890" }), {
    code: "INPUT_LIMIT",
    field: "cpiFrom",
    row: null,
  });
  // A 25-unit label is INPUT_LIMIT even though it is otherwise text.
  assert.deepEqual(errorOf({ ...cpiBase, labelFrom: "1234567890123456789012345" }), {
    code: "INPUT_LIMIT",
    field: "labelFrom",
    row: null,
  });
});

test("a lone surrogate is UNICODE before EMPTY and grammar", () => {
  assert.deepEqual(errorOf({ ...rateBase, amount: "\uD800" }), {
    code: "UNICODE",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...cpiBase, labelFrom: "A\uDC00" }), {
    code: "UNICODE",
    field: "labelFrom",
    row: null,
  });
  assert.deepEqual(errorOf({ ...rateBase, amount: "" }), {
    code: "EMPTY",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...rateBase, years: "" }), {
    code: "EMPTY",
    field: "years",
    row: null,
  });
});

test("decimal grammar: signs, exponents, commas, bad dots and non-ASCII digits are DECIMAL_FORMAT", () => {
  for (const bad of ["+100", "1e3", "1,000", "100.", ".5", "１００", "100 "]) {
    assert.deepEqual(errorOf({ ...rateBase, amount: bad }), {
      code: "DECIMAL_FORMAT",
      field: "amount",
      row: null,
    });
  }
  // A leading "-" is DECIMAL_FORMAT everywhere except annualRatePercent.
  assert.deepEqual(errorOf({ ...rateBase, amount: "-100" }), {
    code: "DECIMAL_FORMAT",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...cpiBase, cpiFrom: "-100" }), {
    code: "DECIMAL_FORMAT",
    field: "cpiFrom",
    row: null,
  });
  // Leading zeros are legal.
  const leadingZero = run({ ...rateBase, amount: "007", years: "0" });
  assert.equal(leadingZero.ok, true);
  assert.equal(leadingZero.result.futureValue, 7);
  // "-0" parses as -0 and is treated as 0.
  const negativeZero = run({ ...rateBase, annualRatePercent: "-0", years: "0" });
  assert.equal(negativeZero.ok, true);
  assert.equal(negativeZero.result.futureValue, 100000);
});

test("integer grammar: decimals, signs, spaces and exponents are INTEGER_FORMAT", () => {
  for (const bad of ["1.5", "-10", "+10", " 10", "1e1", "1.0"]) {
    assert.deepEqual(errorOf({ ...rateBase, years: bad }), {
      code: "INTEGER_FORMAT",
      field: "years",
      row: null,
    });
  }
  assert.deepEqual(errorOf({ ...cpiBase, yearsBetween: "2.5" }), {
    code: "INTEGER_FORMAT",
    field: "yearsBetween",
    row: null,
  });
});

test("labels: only U+0020 is trimmed, internal characters are kept", () => {
  const trimmed = run({ ...cpiBase, labelFrom: "  2015  ", labelTo: "2025 " });
  assert.equal(trimmed.ok, true);
  assert.equal(trimmed.result.fromLabel, "2015");
  assert.equal(trimmed.result.toLabel, "2025");
  // A tab inside the label is kept as-is.
  const tabbed = run({ ...cpiBase, labelFrom: "A\tB", labelTo: "C" });
  assert.equal(tabbed.ok, true);
  assert.equal(tabbed.result.fromLabel, "A\tB");
  // A label of only spaces is EMPTY after trimming.
  assert.deepEqual(errorOf({ ...cpiBase, labelFrom: "   " }), {
    code: "EMPTY",
    field: "labelFrom",
    row: null,
  });
  // A 24-unit label is legal; a 25-unit one is INPUT_LIMIT (checked above).
  const longLabel = run({ ...cpiBase, labelFrom: "123456789012345678901234" });
  assert.equal(longLabel.ok, true);
  assert.equal(longLabel.result.fromLabel, "123456789012345678901234");
});

test("yearsBetween: null means no equivalent rate; an empty string means the same", () => {
  const withNull = run({ ...cpiBase, yearsBetween: null });
  assert.equal(withNull.ok, true);
  assert.equal(withNull.result.equivalentAnnualRatePercent, null);
  const withEmpty = run({ ...cpiBase, yearsBetween: "" });
  assert.equal(withEmpty.ok, true);
  assert.equal(withEmpty.result.equivalentAnnualRatePercent, null);
  assert.deepEqual(errorOf({ ...cpiBase, yearsBetween: "201" }), {
    code: "RANGE",
    field: "yearsBetween",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...rateBase, amount: "abc", annualRatePercent: "-100" }), {
    code: "DECIMAL_FORMAT",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...cpiBase, amount: "abc", cpiFrom: "0" }), {
    code: "DECIMAL_FORMAT",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...cpiBase, cpiFrom: "0", cpiTo: "0" }), {
    code: "RANGE",
    field: "cpiFrom",
    row: null,
  });
  assert.deepEqual(errorOf({ ...cpiBase, labelFrom: "  ", labelTo: "  " }), {
    code: "EMPTY",
    field: "labelFrom",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...rateBase, foo: "1" }), schema);
  const missing = { ...rateBase };
  delete missing.years;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...rateBase, amount: 100000 }), schema);
  assert.deepEqual(errorOf({ ...cpiBase, yearsBetween: 10 }), schema);
  assert.deepEqual(errorOf({ ...rateBase, yearsBetween: null }), schema);
  assert.deepEqual(errorOf(["rate"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("rate"), schema);
  assert.deepEqual(errorOf({ ...rateBase, mode: "cpi" }), schema);
  const withGetter = { ...rateBase };
  Object.defineProperty(withGetter, "amount", {
    enumerable: true,
    get() {
      return "100000";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...rateBase, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...rateBase };
  stringObject.amount = new String("100000");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("the core does not mutate its input", () => {
  const input = { ...rateBase };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...rateBase, amount: "1000000000" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("underflow: factor +0 makes the title purchasing power null and late rows null", () => {
  // SPEC tests: amount 1000, rate -99.999, years 200 -> factor +0,
  // futureValue 0, purchasingPower null, cumulativePercent -100.
  const outcome = run({ mode: "rate", amount: "1000", annualRatePercent: "-99.999", years: "200" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.futureValue, 0);
  assert.equal(outcome.result.purchasingPower, null);
  assert.equal(outcome.result.cumulativePercent, -100);
  // Rows 0..60 stay finite numbers; rows 61..200 are null (row 61's
  // quotient is finite but rounds past the double maximum, so it is
  // null too — never Infinity; see the core's note).
  assert.ok(outcome.result.yearTable.slice(0, 61).every((row) => typeof row.purchasingPower === "number"));
  assert.ok(outcome.result.yearTable.slice(61).every((row) => row.purchasingPower === null));
  assert.ok(outcome.result.yearTable.every((row) => row.nominalValue === 0 || Number.isFinite(row.nominalValue)));
});

test("property: zero rate and identical indices are identities; future value grows with the rate", () => {
  const zero = run({ ...rateBase, annualRatePercent: "0" });
  assert.equal(zero.ok, true);
  assert.equal(zero.result.futureValue, 100000);
  assert.equal(zero.result.purchasingPower, 100000);
  assert.equal(zero.result.cumulativePercent, 0);
  assert.ok(zero.result.yearTable.every((row) => row.nominalValue === 100000 && row.purchasingPower === 100000));
  const same = run({ ...cpiBase, cpiFrom: "101.5", cpiTo: "101.5", yearsBetween: "8" });
  assert.equal(same.ok, true);
  assert.equal(same.result.adjustedAmount, 30000);
  assert.equal(same.result.cumulativePercent, 0);
  assert.equal(same.result.equivalentAnnualRatePercent, 0);
  let previous = -Infinity;
  for (const rate of ["-50", "-1", "0", "2", "10", "100"]) {
    const outcome = run({ ...rateBase, annualRatePercent: rate });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.futureValue > previous);
    previous = outcome.result.futureValue;
  }
});

test("property: the last year-table row equals the title values, and the cumulative sign follows factor - 1", () => {
  for (const input of [
    rateBase,
    { ...rateBase, annualRatePercent: "-1.5", years: "10" },
    { ...rateBase, annualRatePercent: "1000", years: "2" },
    { ...rateBase, years: "0" },
  ]) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    const last = outcome.result.yearTable[outcome.result.yearTable.length - 1];
    assert.equal(last.nominalValue, outcome.result.futureValue);
    assert.equal(last.purchasingPower, outcome.result.purchasingPower);
    assert.equal(
      Math.sign(outcome.result.cumulativePercent),
      Math.sign(outcome.result.futureValue - Number(input.amount)),
    );
  }
  for (const input of [cpiBase, { ...cpiBase, cpiTo: "90.0", yearsBetween: "5" }]) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    assert.equal(
      Math.sign(outcome.result.cumulativePercent),
      Math.sign(outcome.result.adjustedAmount - Number(input.amount)),
    );
  }
});

test("display formatting: grouped thousands, percents, and the null dash", () => {
  assert.equal(formatNumber(121899.44), "121,899.44");
  assert.equal(formatNumber(100000), "100,000");
  assert.equal(formatNumber(0.83), "0.83");
  assert.equal(formatNumber(-14.03), "-14.03");
  assert.equal(formatNumber(0), "0");
  assert.equal(formatNumber(null), "—");
  assert.equal(formatPercent(21.9), "21.9%");
  assert.equal(formatPercent(-100), "-100%");
  assert.equal(formatPercent(1.3185), "1.3185%");
  assert.equal(formatPercent(null), "—");
});
